"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { authClient } from "@/lib/auth-client";

export function AuthForm({ mode }: { mode: "sign-in" | "sign-up" }) {
  const router = useRouter();
  const params = useSearchParams();
  // Only allow same-site relative redirects.
  const rawNext = params.get("next") ?? "/dashboard";
  const next = rawNext.startsWith("/") && !rawNext.startsWith("//") ? rawNext : "/dashboard";
  const [error, setError] = useState<string>();
  const [pending, setPending] = useState(false);
  const isSignUp = mode === "sign-up";

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(undefined);
    setPending(true);
    const form = new FormData(e.currentTarget);
    const email = String(form.get("email"));
    const password = String(form.get("password"));
    const { error } = isSignUp
      ? await authClient.signUp.email({ email, password, name: String(form.get("name")) })
      : await authClient.signIn.email({ email, password });
    setPending(false);
    if (error) return setError(error.message ?? "Something went wrong");
    router.push(next);
    router.refresh();
  }

  return (
    <main className="mx-auto max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isSignUp ? "Create account" : "Sign in"}</h1>
      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {isSignUp && (
          <input name="name" placeholder="Name" required className="w-full rounded border p-2" />
        )}
        <input name="email" type="email" placeholder="Email" required className="w-full rounded border p-2" />
        <input
          name="password"
          type="password"
          placeholder="Password"
          required
          minLength={8}
          autoComplete={isSignUp ? "new-password" : "current-password"}
          className="w-full rounded border p-2"
        />
        {error && <p role="alert" className="text-sm text-red-600">{error}</p>}
        <button disabled={pending} className="w-full rounded bg-foreground p-2 text-background disabled:opacity-50">
          {isSignUp ? "Sign up" : "Sign in"}
        </button>
      </form>
      <button
        type="button"
        className="mt-3 w-full rounded border p-2"
        onClick={() => authClient.signIn.social({ provider: "google", callbackURL: next })}
      >
        Continue with Google
      </button>
      <p className="mt-6 text-sm opacity-70">
        {isSignUp ? (
          <>Have an account? <Link href="/sign-in" className="underline">Sign in</Link></>
        ) : (
          <>New here? <Link href="/sign-up" className="underline">Create an account</Link></>
        )}
      </p>
    </main>
  );
}
